import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    coins = [int(x) for x in data[1:n+1]]

    coins.sort()

    max_val = coins[-1] + coins[-2]

    dp = [float('inf')] * (max_val + 1)
    dp[0] = 0

    for i in range(1, max_val + 1):
        for c in coins:
            if c > i:
                break
            if dp[i - c] != float('inf'):
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1

    def greedy_count(amount):
        count = 0
        idx = n - 1
        current = amount
        while current > 0:
            while idx >= 0 and coins[idx] > current:
                idx -= 1
            if idx < 0:
                break
            count += 1
            current -= coins[idx]
        return count

    for x in range(1, max_val + 1):
        g_count = greedy_count(x)
        opt_count = dp[x]
        if opt_count < g_count:
            print("non-canonical")
            return

    print("canonical")

if __name__ == "__main__":
    main()
